      c=lzma.compress(d,format=lzma.FORMAT_RAW,filters=f)
    except Exception: continue
    res.append((len(c),'lzma1 lc%d pb%d'%(lc,pb)))
res.sort()
for n,k in res[:8]: print(n,round(len(d)/n,4),k)
